class PastelMetric:Control {
 public string Caption="",Value="",Detail="";public Color Fill=Palette.BlueTint;public int Glyph;public bool Breakdown;
 public PastelMetric(){DoubleBuffered=true;ResizeRedraw=true;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.Clear(Palette.Surface(Parent));g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;using(var path=Palette.Round(new RectangleF(1,1,Width-3,Height-3),16))using(var b=new SolidBrush(Fill))g.FillPath(b,path);if(Height<110){MenuGlyph.Draw(g,Glyph,new Rectangle(18,10,26,26),Palette.Accent);using(var small=new Font("맑은 고딕",12,FontStyle.Bold))TextRenderer.DrawText(g,Caption,small,new Rectangle(54,7,Width-66,28),Palette.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);using(var number=new Font("맑은 고딕",23,FontStyle.Bold))TextRenderer.DrawText(g,Value,number,new Rectangle(12,36,Width-24,Height-38),Palette.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);return;}MenuGlyph.Draw(g,Glyph,new Rectangle(24,20,36,36),Palette.Accent);using(var font=new Font("맑은 고딕",14,FontStyle.Bold))TextRenderer.DrawText(g,Caption,font,new Rectangle(75,18,Width-92,38),Palette.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);
  if(Breakdown){var lines=Detail.Split(new[]{'\n'},StringSplitOptions.RemoveEmptyEntries);int step=Math.Min(31,Math.Max(18,(Height-115)/Math.Max(1,lines.Length)));using(var font=new Font("맑은 고딕",11)){for(int i=0;i<lines.Length;i++){var parts=lines[i].Split('\t');var row=new Rectangle(24,62+i*step,Width-48,step);TextRenderer.DrawText(g,parts[0],font,row,Palette.Ink,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);if(parts.Length>1)TextRenderer.DrawText(g,parts[1],font,row,Palette.Ink,TextFormatFlags.Right|TextFormatFlags.VerticalCenter);}}using(var font=new Font("맑은 고딕",24,FontStyle.Bold))TextRenderer.DrawText(g,Value,font,new Rectangle(18,Height-50,Width-36,44),Palette.Ink,TextFormatFlags.Right|TextFormatFlags.VerticalCenter);}

  else{using(var font=new Font("맑은 고딕",Height<125?21:27,FontStyle.Bold))TextRenderer.DrawText(g,Value,font,new Rectangle(18,51,Width-36,Math.Max(30,Height-87)),Palette.Ink,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);using(var font=new Font("맑은 고딕",11))TextRenderer.DrawText(g,Detail,font,new Rectangle(20,Height-35,Width-40,28),Palette.Muted,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);}
 }
