 void UpdatePastelValues(){if(personSummary==null)return;personSummary.Value=String.IsNullOrWhiteSpace(r.Name)?"대상자 미입력":r.Name;personSummary.Detail=jobs[r.JobIndex].name;contractSummary.Value=((r.End.Date-r.Start.Date).Days+1)+"일";contractSummary.Detail=r.Start.ToString("yyyy.MM.dd")+" ~ "+r.End.ToString("yyyy.MM.dd");hoursSummary.Value=r.Hours.ToString("0.##")+"시간";hoursSummary.Detail="1일 소정근로시간";hourlySummary.Value=result.Hourly.ToString("N2")+"원";hourlySummary.Detail=r.HourlyOverride>0?"직접 지정한 시급":result.OrdinaryHourly>=r.Minimum?"통상시급 적용":"최저시급 적용";paySummary.Value=result.Gross.ToString("N0")+"원";paySummary.Detail=String.Join("\n",PayrollItems.Pay(r,result).Select(x=>x.Name+"\t"+x.Amount.ToString("N0")+"원"));deductSummary.Value=result.Deductions.ToString("N0")+"원";deductSummary.Detail="입력 공제 및 고용보험 합계";netSummary.Value=result.Net.ToString("N0")+"원";netSummary.Detail=result.Ready?"최종 실지급액":"예상 금액 · 입력 확인 필요";foreach(var metric in new[]{personSummary,contractSummary,hoursSummary,hourlySummary,paySummary,deductSummary,netSummary})metric.Invalidate();if(personRelayout!=null)personRelayout();UpdatePastelCalendarValues();}
